import{ErrorHandler}from"../../../../libraries/errors/_errors.js";import{getEntireRecitersService,getSpesificReciterService}from"../../../../services/reciter.services.js";const getEntireRecitersController=async(req,res,next)=>{const getEntireReciters=await getEntireRecitersService();return res.status(200).json({success:true,message:"Reciters retrieved successfully",data:getEntireReciters.map(({id,name})=>({id,name}))})};const getSpesificReciterController=async(req,res,next)=>{const getSpesificReciter=await getSpesificReciterService(req.params.reciter);if(!getSpesificReciter){throw new ErrorHandler({code:404,details:[{path:["reciter"],message:`We cannot find reciter '${req.params.reciter}'.`}],message:"NOT_FOUND"})}const formatReciter={id:getSpesificReciter.id,name:getSpesificReciter.name};return res.status(200).json({success:true,message:"Reciter retrieved successfully",data:formatReciter})};export{getEntireRecitersController,getSpesificReciterController};